#include<bits/stdc++.h>
#define mod 998244353

using namespace std;

int main(){
  int n,k;
  cin >> n >> k;
  vector<int> p(n),q(n);
  for(auto &nx : p){cin >> nx;}
  for(auto &nx : q){cin >> nx;}
  vector<int> v(n);
  for(int i=0;i<n;i++){v[p[i]-1]=q[i]-1;}
  vector<vector<int>> dp(k+1,vector<int>(n+1,0));
  dp[0][n]=1;
  for(int i=0;i<n;i++){
    vector<vector<int>> ndp(k+1,vector<int>(n+1,0));
    for(int x=0;x<=k;x++){
      for(int y=0;y<=n;y++){
        if(x<k && v[i]<y){
          ndp[x+1][y]+=dp[x][y];
          ndp[x+1][y]%=mod;
        }
        ndp[x][min(y,v[i])]+=dp[x][y];
        ndp[x][min(y,v[i])]%=mod;
      }
    }
    dp.swap(ndp);
  }
  int res=0;
  for(auto &nx : dp[k]){res+=nx;res%=mod;}
  cout << res << '\n';
  return 0;
}
